const _LB7_USAGE_PINNED = raw"""swipl: Usage:
    1) swipl [options] prolog-file ... [-- arg ...]
    2) swipl [options] [-o executable] -c prolog-file ...
    3) swipl app ...        Use "swipl app list" for available apps
    4) swipl --help         Display this message
    5) swipl --version      Display version information
    6) swipl --abi-version  Display ABI version key
    7) swipl --arch         Display architecture
    8) swipl --dump-runtime-variables[=format]
                            Dump link info in sh(1) format

Options:
    -x state                 Start from state (must be first)
    -g goal                  Run goal (may be repeated)
    -t toplevel              Toplevel goal
    -f file                  User initialisation file
    -F file                  Site initialisation file
    -l file                  Script source file
    -s file                  Script source file
    -p alias=path            Define file search path 'alias'
    -Dname[=value]           Set a Prolog flag (may be repeated)
    -O                       Optimised compilation
    --on-error=style         One of print, halt or status
    --on-warning=style       One of print, halt or status
    --tty[=bool]             (Dis)allow tty control
    --packs[=bool]           Do (not) attach add-ons
    --signals[=bool]         Do (not) modify signal handling
    --sigalert[=num]         Use signal num for alerting threads
    --threads[=bool]         Do (not) allow for threads
    --debug[=bool]           Do (not) generate debug info
    --debug-on-interrupt[=bool] Trap the debugger on interrupt
    --quiet[=bool] (-q)      Do (not) suppress informational messages
    --traditional            Disable extensions of version 7
    --home[=DIR]             Print home or use DIR as SWI-Prolog home
    --stack-limit=size[BKMG] Specify maximum size of Prolog stacks
    --table-space=size[BKMG] Specify maximum size of SLG tables
    --shared-table-space=size[BKMG] Maximum size of shared SLG tables
    --pce[=bool]             Make the xpce gui available
    --pldoc[=port]           Start PlDoc server [at port]

Boolean options may be written as --name=bool, --name, --no-name or --noname.
Both '-' or '_' are accepted as word-separator for long options.
"""
# END GENERATED

"The words of a row after the program name: `-f none -F none` (as the generator), the row's options, the script word of a `run` row."
function _lb7_words(kind::String, args::Vector{String})::Vector{String}
    return String[
        "-f", "none", "-F", "none", args..., (kind == "run" ? ["drv.pl"] : String[])...
    ]
end

# The kernel's database is not booted: `member/2` is swipl's library(lists), which the oracle program gets by autoloading and the unbooted
# kernel cannot load (the autoloader needs the streams of a booted system). The kernel's copy of the program defines it (same clauses as
# lists.pl); the oracle program does not (swipl's own is used). The rows' meaning is the same.
const _LB7_KERNEL_LISTS = "member(X, [X|_]).\nmember(X, [_|T]) :- member(X, T).\n"

"A new database and local data of term type `T` and the parse of `words`: `(gd, ld, left)`, `left` the arguments left to the application, `nothing` for an error."
function _lb7_parse(::Type{T}, words::Vector{String}) where {T}
    gd = LK.PL_global_data{T}()
    ld = LK.PL_local_data{T}(gd)
    left = LK.parseCommandLineOptions(gd, ld, gd.options, gd.cmdline, words)
    return gd, ld, left
end

"The kernel's line for the predicate `name`/1 of the program loaded in `gd`, asked on the engine `ld`: `name` and its answers (at most 50), as the driver writes them."
function _lb7_query(::Type{T}, gd, ld, name::String)::String where {T}
    proc = LK.isCurrentProcedure(sym_key(lk_sym(T, Symbol(name))), 1, LK.MODULE_user(gd))
    if proc === nothing || !LK.isDefinedProcedure(gd, proc)
        return "$name undefined"
    end
    sols = String[]
    rld = ld        # the engine the options were applied to: `stack_limit` reads the querying engine's limit (`ld.stacks_limit`); one query per row
    fid = LK.PL_open_foreign_frame(rld)
    a = LK.PL_new_term_refs(rld, 1)
    LK.putSlotValue!(rld, a + 1, mk_var(T, LK.fresh_var_keys!(1)), LK.PutVarMap())
    qid = LK.PL_open_query(
        gd, rld, nothing, LK.PL_Q_CATCH_EXCEPTION | LK.PL_Q_EXT_STATUS, proc, a
    )
    n = 0
    while (n += 1) <= 50
        rc = LK.PL_next_solution(gd, rld, qid)
        if rc == LK.PL_S_TRUE || rc == LK.PL_S_LAST
            push!(
                sols,
                _lb7_enc(
                    mk_expr(T, T[lk_sym(T, Symbol(name)), lk_answers(rld, (a:a)...)...])
                )
            )
            rc == LK.PL_S_LAST && break
        elseif rc == LK.PL_S_EXCEPTION
            push!(sols, "exception")
            break
        else
            break
        end
    end
    LK.PL_close_query(rld, qid)
    LK.PL_close_foreign_frame(rld, fid)
    return "$name" * join(" " .* sols)
end

"""
The kernel's line for one row: a `usage` row answers `usage` where the parse is an error and `parsed` otherwise; a `run` row parses,
sets the arguments, applies the options to the flags (the `flags` goal), consults the program and answers `t_<id>/1`.
A Julia exception out of a row is its line: `jlerr <type> <what>`.
"""
function _lb7_kernel_line(::Type{T}, dir::String, (id, kind, goal, args)) where {T}
    try
        words = _lb7_words(kind, args)
        gd, ld, left = _lb7_parse(T, words)
        if kind == "usage"
            return left === nothing ? "usage" : "parsed"
        end
        left === nothing && return "t_$id parse failed"
        gd.cmdline.os_argv = String["swipl"; words]
        gd.cmdline.appl_argv = left
        goal == "flags" && LK.apply_options_to_flags!(gd, ld)
        f = joinpath(dir, "prog_$id.pl")
        write(f, _LB7_KERNEL_LISTS * _LB7_HEAD * "t_$(id)(R) :- lb7_$(goal)(R).\n")
        st, ball = LK.load_file!(gd, ld, f)
        st === :ok || return "t_$id load failed " * _lb7_enc(ball::T)
        return _lb7_query(T, gd, ld, "t_$id")
    catch e
        return "jlerr $(nameof(typeof(e)))" * (e isa LK.NotPortedError ? " $(e.what)" : "")
    end
end

"swipl's lines for every row (the generator's command, one process per row); a `usage` row is `usage` when swipl exits 1 with the usage text on stderr."
function _lb7_swipl_lines()::Vector{String}
    return mktempdir() do dir
        write(joinpath(dir, "e1.pl"), "")
        write(joinpath(dir, "e2.pl"), "")
        write(
            joinpath(dir, "prog.pl"),
            _LB7_HEAD * join([
                "t_$(id)(R) :- lb7_$(goal)(R).\n" for
                (id, kind, goal, _) in _LB7_ROWS if kind == "run"
            ])
        )
        outf = joinpath(dir, "out.txt")
        errf = joinpath(dir, "err.txt")
        lines = String[]
        for (id, kind, goal, args) in _LB7_ROWS
            if kind == "run"
                write(
                    joinpath(dir, "drv.pl"),
                    _LB7_DRIVER *
                    ":- initialization((consult('prog.pl'), fz_pred(t_$id), halt)).\n"
                )
            end
            cmd = Cmd(Cmd(String["swipl"; _lb7_words(kind, args)]); dir=dir)
            rc = withenv("LC_ALL" => "C") do
                try
                    run(pipeline(cmd; stdin=devnull, stdout=outf, stderr=errf))
                    0
                catch e
                    e isa ProcessFailedException ? e.procs[1].exitcode : rethrow()
                end
            end
            if kind == "usage"
                push!(
                    lines,
                    if rc == 1 && startswith(read(errf, String), "swipl: Usage:")
                        "usage"
                    else
                        "swipl rc=$rc"
                    end
                )
            else
                push!(lines, rstrip(read(outf, String), '\n'))
            end
        end
        lines
    end
end

# ── the oracle rows ────────────────────────────────────────────────────────────────────────────────────────────

"The row's pin."
_lb7_pin(id::String) = _LB7_PINNED[findfirst(r -> r[1] == id, _LB7_ROWS)::Int]
"An encoded `Key-Value` pair of the driver (`Key` an atom, `value` already encoded)."
_lb7_kv(key::String, value::String) = "c[45]/2(a" * _lb7_codes(key) * "," * value * ")"
_lb7_atom(s::String) = "a" * _lb7_codes(s)

@testset "the options of a command line as swipl's (o, u, f, k rows)" begin
    @test length(_LB7_PINNED) == length(_LB7_ROWS)
    mktempdir() do dir
        for (row, p) in zip(_LB7_ROWS, _LB7_PINNED)
            k = _lb7_kernel_line(_LB7, dir, row)
            k == p || println(stderr, "  ours  ", k, "\n  swipl ", p)
            @test k == p
        end
    end
end

@testset "the oracle rows are not vacuous" begin
    runs = [r for r in _LB7_ROWS if r[2] == "run"]
    usages = [r for r in _LB7_ROWS if r[2] == "usage"]
    # both sides non-empty, one extractor (`_lb7_pin`): every usage row pins `usage`, every run row an answer of its own predicate
    @test length(_LB7_ROWS) >= 40
    @test length(runs) >= 30
    @test length(usages) >= 10
    @test all(r -> _lb7_pin(r[1]) == "usage", usages)
    @test all(r -> startswith(_lb7_pin(r[1]), "t_$(r[1]) "), runs)
    @test count(==("usage"), _LB7_PINNED) == length(usages)
    # the pins say what the options did, and the default says what they did not (a comparison that can pass and fail)
    @test occursin(_lb7_kv("stack_limit", "i1073741824"), _lb7_pin("o01"))
    @test !occursin(_lb7_kv("stack_limit", "i1073741824"), _lb7_pin("o12"))
    @test occursin(_lb7_kv("stack_limit", "i536870912"), _lb7_pin("o12"))           # --stack-limit=512m
    @test occursin(_lb7_kv("stack_limit", "i2147483648"), _lb7_pin("o13"))          # --stack_limit=2g
    @test occursin(_lb7_kv("stack_limit", "i4194304"), _lb7_pin("o14"))             # 4096k
    @test occursin(
        "c[45]/2(" * _lb7_atom("goals") * ",c[91,124,93]/2(" * _lb7_atom("true") * ",",
        _lb7_pin("o02")
    )
    @test !occursin(_lb7_kv("goals", "nil"), _lb7_pin("o02"))
    @test occursin(_lb7_kv("goals", "nil"), _lb7_pin("o01"))                         # [] in the default
    @test occursin(_lb7_kv("nosignals", _lb7_atom("true")), _lb7_pin("o09"))
    @test occursin(_lb7_kv("nosignals", _lb7_atom("false")), _lb7_pin("o11"))
    @test !occursin(_lb7_kv("defines", "nil"), _lb7_pin("o07"))
    @test occursin(_lb7_kv("defines", "nil"), _lb7_pin("o08"))                       # an early define is dropped
    @test !occursin("a" * _lb7_codes("config"), _lb7_pin("o01"))                     # an unset STRING option: no entry, not `[]`
    @test !occursin("a" * _lb7_codes("pldoc_server"), _lb7_pin("o01"))
    @test occursin(_lb7_kv("optimise", _lb7_atom("true")), _lb7_pin("f02"))
    @test occursin(_lb7_kv("optimise", _lb7_atom("false")), _lb7_pin("f01"))
    @test occursin(_lb7_kv("verbose", _lb7_atom("silent")), _lb7_pin("f03"))
    @test occursin(_lb7_kv("verbose", _lb7_atom("normal")), _lb7_pin("f01"))
    @test occursin(_lb7_kv("packs", _lb7_atom("false")), _lb7_pin("f09"))
    @test occursin(
        "c" * _lb7_codes("existence_error") * "/2(" * _lb7_atom("cmd_option") * ",",
        _lb7_pin("k01")
    )
    @test occursin(_lb7_atom("same"), _lb7_pin("k03"))
    @test _lb7_pin("o01") != _lb7_pin("o02")
end

@testset "the pins are swipl's (live, when swipl is on PATH)" begin
    swipl = get(ENV, "LOGICKERNEL_NO_SWIPL", "") == "1" ? nothing : Sys.which("swipl")
    # the pinned table is the generator's whole output (the inert-testset guard: an assertion either way)
    @test length(_LB7_PINNED) == length(_LB7_ROWS)
    @test !isempty(_LB7_USAGE_PINNED)
    if swipl === nothing
        @info "LB7 LIVE CHECK NOT RUN: `swipl` is not on PATH here. It runs in tools/run_tests.sh and CI."
    else
        lines = _lb7_swipl_lines()
        for (row, l, p) in zip(_LB7_ROWS, lines, _LB7_PINNED)
            l == p || println(stderr, "  swipl ", l, "\n  pin   ", p)
            @test l == p
        end
        @test length(lines) == length(_LB7_PINNED)
        mktempdir() do dir
            errf = joinpath(dir, "help.txt")
            withenv("LC_ALL" => "C") do
                run(
                    pipeline(
                        ignorestatus(`swipl --help`);
                        stdin=devnull,
                        stdout=devnull,
                        stderr=errf
                    )
                )
            end
            @test read(errf, String) == _LB7_USAGE_PINNED
        end
    end
end

# ── '$usage'/0 and the usage text ──────────────────────────────────────────────────────────────────────────────

@testset "usage text is swipl --help's" begin
    # the text with the program name (`swipl` always: pl-init.c `usage`), and the table that registers `$usage/0` (pl-init.c BeginPredDefs(init))
    @test LK.usage_text() == _LB7_USAGE_PINNED
    @test startswith(LK.usage_text(), "swipl: Usage:\n")
    @test !occursin("%s", LK.usage_text())
    @test occursin("%s", LK.USAGE_TEXT)                       # the template is not the text: the comparison above can fail
    @test count(==('\n'), LK.usage_text()) == count(==('\n'), _LB7_USAGE_PINNED) >= 30
    @test length(LK.PL_predicates_from_init) == 1
    ext = LK.PL_predicates_from_init[1]
    @test ext.predicate_name == "\$usage" && ext.arity == 0
end

# ── hand-written rows: the static C functions (the oracle rows above pin their effect) ─────────────────────────

# optcmp (pl-init.c:127-144): `-` of the word matches `_` of the option name and the other way round; the word may go on after the name
# (`=value`, or anything: "quietly" is the name "quiet" with the rest "ly", the quirk that makes `--quietly` a usage error, row u07); `=` is
# consumed and kept out of the rest. Pinned by o12/o13 (`--stack-limit=` and `--stack_limit=`), u07.
@testset "optcmp" begin
    rows = [
        ("stack-limit=10k", "stack_limit", "10k"),
        ("stack_limit=10k", "stack_limit", "10k"),
        ("stack-limit=10k", "stack-limit", "10k"),
        ("stack_limit", "stack-limit", ""),
        ("quiet=false", "quiet", "false"),
        ("quiet=", "quiet", ""),
        ("quietly", "quiet", "ly"),
        ("quiet=a=b", "quiet", "a=b"),
        ("stackx", "stack_limit", nothing),
        ("qui", "quiet", nothing),
        ("", "quiet", nothing),
        ("Quiet", "quiet", nothing)
    ]
    for (av, opt, want) in rows
        @test LK.optcmp(av, opt) == want
        @test LK.is_longopt(av, opt) == want
    end
    @test count(r -> r[3] === nothing, rows) >= 3 && count(r -> r[3] !== nothing, rows) >= 6   # both outcomes
end

# is_bool_opt (pl-init.c:275-305): `name`, `name=true|yes|y|false|no|n` (strcasecmp on the value), `no-name`, `no_name`, `noname`;
# a value that is no boolean is -1 (a usage error: u01, u11), another option 0. Pinned by o09-o11, o16, u01, u11.
@testset "is_bool_opt" begin
    rows = [
        ("quiet", "quiet", (1, true)),
        ("quiet=true", "quiet", (1, true)),
        ("quiet=YES", "quiet", (1, true)),
        ("quiet=y", "quiet", (1, true)),
        ("quiet=false", "quiet", (1, false)),
        ("quiet=No", "quiet", (1, false)),
        ("quiet=n", "quiet", (1, false)),
        ("quiet=maybe", "quiet", (-1, false)),
        ("noquiet", "quiet", (1, false)),
        ("no-quiet", "quiet", (1, false)),
        ("no_quiet", "quiet", (1, false)),
        ("no-quiet=false", "quiet", (-1, false)),
        ("no-debug", "debug", (1, false)),
        ("debug", "quiet", (0, false)),
        ("QUIET", "quiet", (0, false)),
        ("no", "quiet", (0, false)),
        ("quietly", "quiet", (-1, false))
    ]
    for (opt, name, want) in rows
        @test LK.is_bool_opt(opt, name) == want
    end
    @test count(r -> r[3][1] == 1, rows) >= 10 && count(r -> r[3][1] == -1, rows) >= 2 &&
        count(r -> r[3][1] == 0, rows) >= 3                              # all three outcomes
end

# find_define (pl-init.c:211-239): the value of `-Dname[=value]` in the raw words, the last one wins, the scan ends at `--`, `-D name=value` is
# two words, `-Dname` has the value ""; "foo2=1" is `foo` with the rest "2=1" (optcmp's rest). Pinned by o07 (the lists), o08 (an early define).
@testset "find_define" begin
    rows = [
        (["-Dfoo=bar"], "foo", "bar"),
        (["-Dfoo=bar", "-Dfoo=baz"], "foo", "baz"),
        (["-Dfoo=1", "--", "-Dfoo=2"], "foo", "1"),
        (["--", "-Dfoo=2"], "foo", nothing),
        (["-D", "foo=bar"], "foo", "bar"),
        (["-Dfoo"], "foo", ""),
        (["-Dfoo2=1"], "foo", "2=1"),
        (["-D"], "foo", nothing),
        (["-q", "-O", "x.pl"], "foo", nothing),
        (["-Dbar=1"], "foo", nothing)
    ]
    for (argv, name, want) in rows
        @test LK.find_define(name, argv) == want
    end
    @test count(r -> r[3] === nothing, rows) >= 3 && count(r -> r[3] !== nothing, rows) >= 5
    @test LK.is_early_define("file_name_case_handling=case_sensitive")
    @test LK.is_early_define("file_name_case_handling")
    @test !LK.is_early_define("foo=bar")
end

# memarea_limit (pl-init.c:780-806): an integer and an optional suffix k/m/g (binary) or b. DIVERGES from C: a negative number and a number
# above 64 bits are invalid (C casts them to size_t). Pinned by o12-o14 (512m, 2g, 4096k), u04, u05, u10.
@testset "memarea_limit" begin
    gd = LK.PL_global_data{_LB7}()
    ld = LK.PL_local_data{_LB7}(gd)
    rows = [
        ("10k", 10240),
        ("10K", 10240),
        ("1m", 1 << 20),
        ("512M", 512 << 20),
        ("2g", 2 << 30),
        ("3b", 3),
        ("3B", 3),
        ("7", 7),
        ("0", 0),
        ("5x", nothing),
        ("", nothing),
        ("bad", nothing),
        ("-5", nothing),
        ("99999999999999999999", nothing)
    ]
    for (s, want) in rows
        @test LK.memarea_limit(ld, s) == want
    end
    @test count(r -> r[2] === nothing, rows) >= 4 && count(r -> r[2] !== nothing, rows) >= 8
end

# parseCommandLineOptions (pl-init.c:1113-1347): the arguments left for the application. Pinned by the oracle rows for the options' effect
# (o, u); the split (where the options end) is the C loop: the first word that is no option, or `--` (kept, with all after it).
@testset "parseCommandLineOptions: the arguments left" begin
    rows = [
        (String[], String[]),
        (["-f", "none", "x.pl", "a"], ["x.pl", "a"]),
        (["-g", "t", "--", "x"], ["--", "x"]),
        (["--", "x"], ["--", "x"]),
        (["--", "-q"], ["--", "-q"]),                 # `--` ends the options: what follows it is not read as one (pl-init.c:1186)
        (["-g", "t", "--", "-z"], ["--", "-z"]),
        (["-z"], ["-z"]),
        (["-q", "-z"], ["-z"]),
        (["--foo"], ["--foo"]),                       # an unknown long option stays for argv_prolog_files (swipl: `$usage` there, exit 1)
        (["-d", "topic", "-q"], String[]),            # DIVERGES (ruling Q7): `-d topic` takes its word and is ignored
        (["-c"], String[]),
        (["-x", "s"], String[]),
        (["--home=/x"], String[]),
        (["--pldoc=4000"], String[]),
        (["--pce"], String[]),
        (["--no-pce"], String[]),
        (["--sigalert=5"], String[]),
        (["-Dfoo"], String[]),
        (["-q", "x.pl", "-q"], ["x.pl", "-q"]),
        (["--sigalert=99"], nothing),
        (["--sigalert=x"], nothing),
        (["-D"], nothing),
        (["-g"], nothing),
        (["-qz"], nothing),
        (["--quiet=maybe"], nothing)
    ]
    for (words, want) in rows
        _, _, left = _lb7_parse(_LB7, words)
        left == want ||
            println(stderr, "  ours ", repr(left), "  want ", repr(want), "  for ", words)
        @test left == want
    end
    @test count(r -> r[2] === nothing, rows) >= 4 &&
        count(r -> r[2] !== nothing, rows) >= 12
    @test count(r -> r[2] !== nothing && !isempty(r[2]), rows) >= 6                 # a non-empty rest and an empty one
end

@testset "parseCommandLineOptions: the options set" begin
    p(words) = _lb7_parse(_LB7, words)
    gd, _, _ = p(["-c"])
    @test gd.options.compile
    gd, _, _ = p(String[])
    @test !gd.options.compile
    gd, _, _ = p(["-x", "s"])
    @test gd.options.bootFrom == "s"
    gd, _, _ = p(["-f", "ini", "-F", "sys", "-o", "out", "-t", "tl"])
    @test (
        gd.options.initFile,
        gd.options.systemInitFile,
        gd.options.compileOut,
        gd.options.topLevel
    ) ==
        ("ini", "sys", "out", "tl")
    gd, _, _ = p(["--pldoc=4000"])
    @test gd.options.pldoc_server == "4000"
    gd, _, _ = p(["--pldoc"])
    @test gd.options.pldoc_server == ""
    gd, _, _ = p(String[])
    @test gd.options.pldoc_server === nothing
    gd, _, _ = p(["--pce"])
    @test gd.options.xpce == 1
    gd, _, _ = p(["--no-pce"])
    @test gd.options.xpce == 0
    gd, _, _ = p(String[])
    @test gd.options.xpce == -1
    gd, _, _ = p(["-q"])
    @test gd.options.silent
    gd, _, _ = p(["--quiet"])
    @test gd.options.silent
    gd, _, _ = p(["--no-quiet"])
    @test !gd.options.silent
    gd, _, _ = p(["--no-threads"])
    @test gd.options.nothreads
    gd, _, _ = p(["--on-error=halt", "--on-warning=status"])
    @test (gd.options.on_error, gd.options.on_warning) == ("halt", "status")
    gd, _, _ = p(["--table-space=64m", "--shared-table-space=1g"])
    @test (gd.options.tableSpace, gd.options.sharedTableSpace) == (64 << 20, 1 << 30)
    gd, _, _ = p(["--dump-runtime-variables"])
    @test gd.options.config == ""
    gd, _, _ = p(["-Dfoo", "-D", "a=b", "-Dfile_name_case_handling=x"])
    @test gd.options.defines == ["foo", "a=b"]
    gd, _, _ = p(["-O"])
    @test gd.cmdline.optimise
    gd, _, _ = p(["--no-packs"])
    @test !gd.cmdline.packs
    gd, _, _ = p(String[])
    @test gd.cmdline.packs && !gd.cmdline.optimise
    gd, _, _ = p(["-b"])
    @test gd.bootsession
    @test_throws LK.NotPortedError p(["--traditional"])                          # DIVERGES (3): the kernel is SWI-7 only
end

# initDefaultOptions (pl-init.c:1073-1092), the options a new database holds before any word is read. Pinned by o01 (the defaults in the pin).
@testset "initDefaultOptions!" begin
    gd = LK.PL_global_data{_LB7}()
    o = gd.options
    @test o.stackLimit == 1 << 30 && o.tableSpace == 1 << 30 &&
        o.sharedTableSpace == 1 << 30
    @test o.compileOut == "a.out" && o.topLevel == "default" && o.saveclass == "none"
    @test o.on_error == "print" && o.on_warning == "print"
    @test o.initFile === nothing && o.bootFrom === nothing && o.config === nothing
    @test isempty(o.goals) && isempty(o.scriptFiles) && isempty(o.search_paths) &&
        isempty(o.defines)
    # a second call resets what a parse set; the keyword arguments are the build's constants
    o.scriptFiles = ["x.pl"]
    o.goals = ["g1", "g2"]
    o.bootFrom = "s"
    o.stackLimit = 5
    LK.initDefaultOptions!(o; stack_limit=1 << 20, toplevel="tl", startup="st", goal="g0")
    @test o.stackLimit == 1 << 20 && o.topLevel == "tl" && o.initFile == "st"
    @test o.goals == ["g0"] && isempty(o.scriptFiles) && o.bootFrom === nothing
    LK.initDefaultOptions!(o)
    @test o.stackLimit == 1 << 30 && isempty(o.goals) && o.initFile === nothing
end

# OPTDEFS (pl-prims.c:6358-6377) in upstream's order, and the registration of the two predicates right after `statistics/2`
# (BeginPredDefs(prims)). Pinned by o01 (the keys, in the generator's lb7_keys order, are these minus `home`) and k01-k05.
@testset "OPTDEFS and the prims table" begin
    @test [d[1] for d in LK.OPTDEFS] == [
        "stack_limit", "goals", "toplevel", "init_file", "system_init_file", "script_file",
        "config",
        "compileout", "class", "search_paths", "defines", "pldoc_server", "nosignals",
        "home"
    ]
    @test [d[2] for d in LK.OPTDEFS] == [
        LK.CMDOPT_SIZE_T, LK.CMDOPT_LIST, LK.CMDOPT_STRING, LK.CMDOPT_STRING,
        LK.CMDOPT_STRING, LK.CMDOPT_LIST,
        LK.CMDOPT_STRING, LK.CMDOPT_STRING, LK.CMDOPT_STRING, LK.CMDOPT_LIST,
        LK.CMDOPT_LIST, LK.CMDOPT_STRING,
        LK.CMDOPT_BOOL, LK.CMDOPT_STRING
    ]
    @test [d[3] for d in LK.OPTDEFS] == [
        :stackLimit, :goals, :topLevel, :initFile, :systemInitFile, :scriptFiles, :config,
        :compileOut,
        :saveclass, :search_paths, :defines, :pldoc_server, :nosignals, :home
    ]
    names = [e.predicate_name for e in LK.PL_predicates_from_prims]
    i = findfirst(==("statistics"), names)
    @test i !== nothing
    @test names[(i + 1):(i + 2)] == ["\$cmd_option_val", "\$cmd_option_set"]
    @test [e.arity for e in LK.PL_predicates_from_prims[(i + 1):(i + 2)]] == [2, 2]
    # the keys of the table are the generator's keys plus `home` (k03 reads it): the oracle's `$cmd_option_val` answers each of them
    for (name, _, _) in LK.OPTDEFS
        name == "home" && continue
        @test occursin("c[45]/2(a" * _lb7_codes(name) * ",", _lb7_pin("o01")) ==
            !(name in ("config", "pldoc_server"))
    end
end

# defaultSystemInitFile (pl-init.c:738-759): the leading letters, digits, `_` and `-` of the base name of the program (isAlpha is the
# letter/digit/`_` class), `swipl` where there are none. MEASURED on swipl 10.1.19 with the binary linked as each name and `-f none` (the flag
# `system_init_file` is the answer): swipl-9x -> swipl-9x, 9lives -> 9lives, my-swipl.exe -> my-swipl, a_b-c.d -> a_b-c, "a+b" -> a,
# sw-pl.1x -> sw-pl, .hid -> swipl; "" is read from the source (no leading character: swipl).
@testset "defaultSystemInitFile" begin
    rows = [
        ("/usr/bin/swipl", "swipl"),
        ("swipl", "swipl"),
        ("swipl-9x", "swipl-9x"),
        ("/x/9lives", "9lives"),
        ("my-swipl.exe", "my-swipl"),
        ("a_b-c.d", "a_b-c"),
        ("a+b", "a"),
        ("sw-pl.1x", "sw-pl"),
        (".hid", "swipl"),
        ("", "swipl")
    ]
    for (a0, want) in rows
        @test LK.defaultSystemInitFile(a0) == want
    end
    @test count(r -> r[2] == "swipl", rows) >= 3 && count(r -> r[2] != "swipl", rows) >= 5
end

# apply_options_to_flags!: the stack limit goes to the local data in words (DIVERGES 3: `ld.stacks_limit` is bytes ÷ 8 here); the flags
# themselves are pinned by the f rows (oracle).
@testset "apply_options_to_flags!: the stack limit in words" begin
    gd = LK.PL_global_data{_LB7}()
    ld = LK.PL_local_data{_LB7}(gd)
    LK.apply_options_to_flags!(gd, ld)
    @test ld.stacks_limit == (1 << 30) ÷ 8
    # the STORED flag (the global table's entry): `current_prolog_flag(stack_limit, V)` answers from `ld.stacks_limit * 8`, so the
    # f rows never see it
    sl_key = LK._atom_word!(gd.atoms, gd.atom_symbols, LK.mk_sym(_LB7, :stack_limit))
    sl = LK._prolog_flag_table_get(gd, sl_key)
    @test sl !== nothing && sl.i == gd.options.stackLimit == 1 << 30
    gd.options.stackLimit = 1 << 20
    LK.apply_options_to_flags!(gd, ld)
    @test ld.stacks_limit == (1 << 20) ÷ 8
    @test ld.stacks_limit != (1 << 30) ÷ 8
    sl = LK._prolog_flag_table_get(gd, sl_key)
    @test sl !== nothing && sl.i == gd.options.stackLimit == 1 << 20
    @test sl.i != 1 << 30
end
